draw = r'''function draw(i,p,t){p=Math.min(1,(t-STEPS.slice(0,i).reduce((a,s)=>a+(s.d||0),0))/Math.min(3.2,STEPS[i].d));const kinds=['isekai','stats','dice','contract','conflict','condition','xp','growth','combat','travel','agency'];for(const k of kinds)$(k==='isekai'?'world':k).setAttribute('opacity',STEPS[i].kind===k?'1':'0');const s=STEPS[i];const set=(id,a,v)=>$(id).setAttribute(a,v);const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
 if(s.kind==='isekai'){set('steve','cx',325+475*p);set('steve','cy',256-18*Math.sin(p*Math.PI));}
 if(s.kind==='stats'){set('stats','opacity','1');let g=$('bars');if(!g.childNodes.length){['СИЛ','ЛОВ','ТЕЛ','ИНТ','МДР','ХАР'].forEach((n,j)=>{let y=145+j*47;g.insertAdjacentHTML('beforeend',`<text x="260" y="${y+19}" fill="#8b93a7" font-size="19">${n}</text><rect x="320" y="${y}" width="500" height="25" rx="12" fill="#202c3c"/><rect id="bar${j}" x="320" y="${y}" width="0" height="25" rx="12" fill="#58c4dd"/><text id="val${j}" x="850" y="${y+20}" fill="#f0ac5f" font-size="21">0</text>`)});}let vals=[10,12,10,14,7,12];vals.forEach((v,j)=>{set('bar'+j,'width',500*v/20*p);$('val'+j).textContent=Math.round(v*p)});}
 if(s.kind==='dice'){set('dice','opacity','1');set('dice','transform',`rotate(${Math.sin(p*Math.PI*2)*18} 600 255)`);$('roll').textContent=p>.72?'15':'·';}
 if(s.kind==='contract'){set('contract','opacity','1');set('energy','cx',245+510*p);let g=$('gates');if(!g.childNodes.length){['ИСТОЧНИК','ЦЕЛЬ','ВРЕМЯ','ЦЕНА','ЗАЩИТА','ОСВОЕНИЕ'].forEach((n,j)=>{let x=195+(j%3)*315,y=145+Math.floor(j/3)*215;g.insertAdjacentHTML('beforeend',`<rect id="gate${j}" x="${x}" y="${y}" width="210" height="58" rx="15" fill="#202c3c" stroke="#2a3142" stroke-width="2"/><text x="${x+105}" y="${y+36}" fill="#8b93a7" text-anchor="middle" font-size="18">${n}</text>`)});}let local=STEPS.slice(0,i).filter(x=>x.chapter===s.chapter).length;for(let j=0;j<6;j++)set('gate'+j,'stroke',j<local||j<Math.ceil(p*6)?'#83c167':'#2a3142');}
 if(s.kind==='conflict'){set('conflict','opacity','1');let y=170;set('shot','cy',y);set('shot','cx',p<.7?260+515*p/.7:775-295*(p-.7)/.3);}
 if(s.kind==='condition'){set('condition','opacity','1');let g=$('tracks');if(!g.childNodes.length){['ЗДОРОВЬЕ','МАНА','УСТАЛОСТЬ'].forEach((n,j)=>{let y=145+j*42;g.insertAdjacentHTML('beforeend',`<text x="780" y="${y+17}" fill="#8b93a7" font-size="18">${n}</text><rect x="780" y="${y+24}" width="210" height="12" rx="6" fill="#202c3c"/><rect id="track${j}" x="780" y="${y+24}" width="0" height="12" rx="6" fill="${['#58c4dd','#83c167','#f0ac5f'][j]}"/>`)});}for(let j=0;j<3;j++)set('track'+j,'width',210*(j===0?.72:j===1?.45:.25+0.65*p));}
 if(s.kind==='xp'){set('xp','opacity','1');let f=p;set('xpbar','d',`M230 380H${230+740*f}`);let g=$('milestones');if(!g.childNodes.length){['','','','6 500 XP'].forEach((n,j)=>{let x=230+[300/6500*740,900/6500*740,2700/6500*740,740][j];g.insertAdjacentHTML('beforeend',`<circle cx="${x}" cy="380" r="11" fill="#151a24" stroke="#f0ac5f" stroke-width="4"/><text x="${x}" y="332" fill="#8b93a7" text-anchor="middle" font-size="17">${n}</text>`)});}let marks=$('xpmarks');if(!marks.childNodes.length){['практика','задача','открытие','опасность'].forEach((n,j)=>{let x=310+j*190;marks.insertAdjacentHTML('beforeend',`<circle id="xpmark${j}" cx="${x}" cy="${230+(j%2)*42}" r="16" fill="#202c3c" stroke="#83c167" stroke-width="3"/><text x="${x}" y="${200+(j%2)*42}" text-anchor="middle" fill="#8b93a7" font-size="18">${n}</text>`);set('xpmark'+j,'opacity','1')})}for(let j=0;j<4;j++)set('xpmark'+j,'opacity',p>j*.19?'1':'.25');}
 if(s.kind==='growth'){set('growth','opacity','1');let g=$('tiers');if(!g.childNodes.length){['Не изучена','Новичок','Практика','Мастер'].forEach((n,j)=>{let x=250+j*215,h=70+j*55,y=385-h;g.insertAdjacentHTML('beforeend',`<rect id="tier${j}" x="${x}" y="${y}" width="130" height="${h}" rx="14" fill="#202c3c" stroke="#58c4dd" stroke-width="3"/><text x="${x+65}" y="${y-14}" text-anchor="middle" fill="#8b93a7" font-size="17">${n}</text>`)});}let q=(i%7+1)/7*p;for(let j=0;j<4;j++)set('tier'+j,'fill',j<q*4?'#294135':'#202c3c');set('growthline','d',`M250 370L${250+q*645} ${370-q*225}`);}
 if(s.kind==='combat'){set('combat','opacity','1');set('damageexample','opacity',s.t==='Бронепробитие имеет доли'?'1':'0');$('damageexampletext').textContent=p<.5?'ПРИМЕР: PEN 3 · PROT 4 · УРОН 8':'3 > 4 / 2 → ПОЛОВИНА УРОНА: 8 → 4';let g=$('weapons');if(!g.childNodes.length){['МУШКЕТ','РЕВОЛЬВЕР','ВИНТОВКА','МАГИТЕХ'].forEach((n,j)=>{let x=245+j*240;g.insertAdjacentHTML('beforeend',`<path d="M${x} 200h145v16h-145zM${x+22} 216v19h18v-19M${x+118} 216v15" fill="none" stroke="${['#8b93a7','#58c4dd','#83c167','#f0ac5f'][j]}" stroke-width="7" stroke-linecap="round"/><text x="${x+70}" y="273" text-anchor="middle" fill="#8b93a7" font-size="16">${n}</text>`)});}set('penetration','d',`M260 368H${260+680*p}`);}
 if(s.kind==='travel'){set('travel','opacity','1');let route=$('travelroute'),point=route.getPointAtLength(p*route.getTotalLength());set('traveler','cx',point.x);set('traveler','cy',point.y);set('timebar','d',`M310 130H${310+580*p}`);}
 if(s.kind==='agency'){set('agency','opacity','1');set('recordpath','stroke-dashoffset',String(320*(1-p)));let g=$('clues');if(!g.childNodes.length){[0,1,2].forEach(j=>g.insertAdjacentHTML('beforeend',`<circle id="clue${j}" cx="${360+j*240}" cy="${465-(j%2)*28}" r="12" fill="#f0ac5f" opacity="0"/>`));}for(let j=0;j<3;j++)set('clue'+j,'opacity',p>(j+1)/4?'1':'0');}
}'''

source = TEMPLATE_SOURCE.read_text()
match = re.search(r"```html motion-template\n(.*?)\n```", source, re.S)
if not match:
    raise SystemExit("html-motion player scaffold not found")
html = match.group(1)
html = html.replace("<title>Title</title>", "<title>Правила аниме-исэкая — видео и плеер</title>")
html = html.replace("<h1>Title: what we explain</h1>", "<h1>Аниме-исэкай: правила мира, боя и роста</h1>")
html = re.sub(r'<svg id="stage".*?</svg>', svg, html, count=1, flags=re.S)
html = re.sub(r"const STEPS = \[.*?\n\];\n// ── PLAYER ──", "const STEPS = " + json.dumps(steps, ensure_ascii=False) + ";\nwindow.voice?.(STEPS);\n" + draw + "\n// ── PLAYER ──", html, count=1, flags=re.S)
if "window.voice?.(STEPS);" not in html or "function draw(i,p,t)" not in html:
    raise SystemExit("voice hook or deterministic frame function missing")
ROOT.joinpath("campaign-rules-ru.html").write_text(html)
script = ["# Сценарий озвучки — правила аниме-исэкая", "", "Источник: `worker-brief.md`, `public-context.json` и `campaign-rules.md`.", "Нумерация шагов соответствует главам и субтитрам.", ""]
for chapter, heading, kind, items in chapters:
    script += [f"## {chapter}", ""]
    for title, say, sub, note in items:
        script += [f"### {title}", say, ""]
ROOT.joinpath("script.md").write_text("\n".join(script))
print(f"created {len(steps)} narrated steps in {ROOT / 'campaign-rules-ru.html'}")
